from pathlib import Path
import hashlib,json,re
q=Path(__file__).resolve().parent;root=q.parents[1]
base=(root/'qa/calibration-20261024/candidate.html').read_text();assert hashlib.sha256(base.encode()).hexdigest()=='728f4afac83aa6290a5c9241d2f0ee8885b6b363f1af6dd78736986a12ee9fc4'
source=(root/'v8/ui/components.js').read_text();line=next(x for x in source.splitlines()if x.startswith('  const cardStats='));original="  const cardStats=p.role==='BOWL'?[['Bowling',p.bowl],['Accuracy',p.bowlControl],['Fielding',p.fielding]]:p.role==='WK-BAT'?[['Batting',p.bat],['Keeping',p.keeping],['Fielding',p.fielding]]:p.role==='AR'?[['Batting',p.bat],['Bowling',p.bowl],['Fielding',p.fielding]]:[['Batting',p.bat],['Power',p.power],['Fielding',p.fielding]];";before=source.replace(line,original);assert base.count(before)==1;h=base.replace(before,source,1)
css=(root/'v8/ui/workspace.css').read_text();before=css.replace('overall rail, identity, two role-relevant abilities.','overall rail, identity, three cricket attributes.').replace('.g8cardattributes{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));','.g8cardattributes{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));').replace('.g8cardattributes{grid-template-columns:repeat(2,minmax(0,1fr));gap:0}', '.g8cardattributes{grid-template-columns:repeat(auto-fit,minmax(min(100%,5rem),1fr));gap:.5rem}.g8cardattributes>span+span{border-left:0}');assert h.count(before)==1;h=h.replace(before,css,1)
for path in ['game/gcc_v8_product_candidate.html','game/gcc_v8_quiet_arcade.html']:(root/path).write_text(h)
q.joinpath('candidate.html').write_text(h);# Delivery copy is staged separately after verification.
blocks=lambda s:[m[1]for m in re.finditer(r'<script\b[^>]*>([\s\S]*?)</script>',s)]
changed=[i for i,(a,b)in enumerate(zip(blocks(base),blocks(h)))if a!=b];assert len(changed)==1
r={'hash':hashlib.sha256(h.encode()).hexdigest(),'baselineHash':hashlib.sha256(base.encode()).hexdigest(),'gitBlob':hashlib.sha1(b'blob '+str(len(h.encode())).encode()+b'\0'+h.encode()).hexdigest(),'changedScriptBlocks':changed,'source':'v8/ui/components.js + v8/ui/workspace.css','simulationAndSaveCodeChanged':False,'cardAbilities':{'BAT':['Batting','Fielding'],'BOWL':['Bowling','Fielding'],'AR':['Batting','Bowling'],'WK-BAT':['Batting','Keeping']}};q.joinpath('build.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r))
